Action.Str:
// Shared BeanShell API implementation for Santa Fe Direct. Installed inside Tasker.
// Request recipes match the working API Lab 0.3.3. No external script is loaded.
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.security.MessageDigest;
import org.json.*;
import okhttp3.*;

String sfValue(String name) {
    String value = tasker.getVariable(name);
    return value == null ? "" : value;
}
void sfFail(String message) { throw new IOException("SF: " + message); }
long sfNow() { return System.currentTimeMillis(); }
void sfDelay(long milliseconds) { Thread.sleep(milliseconds); }
OkHttpClient sfMakeClient() {
    return new OkHttpClient.Builder().connectTimeout(20, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS).writeTimeout(20, TimeUnit.SECONDS)
        .callTimeout(45, TimeUnit.SECONDS).followRedirects(false).followSslRedirects(false)
        .retryOnConnectionFailure(false).cookieJar(CookieJar.NO_COOKIES).cache(null).build();
}
String sfIdentity(String email, String password, String pin) {
    JSONObject identity = new JSONObject().put("email", email).put("password", password).put("pin", pin);
    byte[] bytes = MessageDigest.getInstance("SHA-256").digest(identity.toString().getBytes("UTF-8"));
    StringBuilder encoded = new StringBuilder();
    for (int i = 0; i < bytes.length; i++) encoded.append(String.format("%02x", new Object[]{Integer.valueOf(bytes[i] & 255)}));
    return encoded.toString();
}
String sfHeader(Object value) {
    if (value == null) sfFail("An API header is missing. Run SFD Connect. No command was sent.");
    String text = String.valueOf(value);
    if (text.length() == 0 || text.length() > 8192 || text.indexOf('\r') >= 0 || text.indexOf('\n') >= 0)
        sfFail("An API header is invalid. No command was sent.");
    return text;
}
String sfEnrollmentPath(String email) {
    // Match encodeURIComponent, preserving literal @ only. Encode other delimiters.
    String encoded = URLEncoder.encode(email, "UTF-8").replace("+", "%20")
        .replace("%21", "!").replace("%27", "'").replace("%28", "(")
        .replace("%29", ")").replace("%7E", "~").replace("%40", "@");
    return "/ac/v2/enrollment/details/" + encoded;
}
boolean sfAllowedPath(String method, String path) {
    if (method.equals("GET")) return path.startsWith("/ac/v2/enrollment/details/")
        || path.equals("/ac/v2/rcs/rvs/vehicleStatus") || path.equals("/ac/v2/rmt/getRunningStatus");
    if (method.equals("POST")) return path.equals("/v2/ac/oauth/token")
        || path.equals("/ac/v2/rcs/rdo/on") || path.equals("/ac/v2/rcs/rdo/off")
        || path.equals("/ac/v2/rcs/rsc/start") || path.equals("/ac/v2/rcs/rsc/stop");
    return false;
}
JSONObject sfRequest(String method, String path, JSONObject body, boolean auth, boolean vehicle, Map extra) {
    if (!sfAllowedPath(method, path) || path.indexOf('?') >= 0 || path.indexOf('#') >= 0)
        sfFail("This API operation is not allowed. No request was sent.");
    long until = 0;
    try { until = Long.parseLong(sfValue("SFDWaitUntil")); } catch (Exception ignored) {}
    if (sfNow() < until) sfFail("Hyundai rate limited requests. Wait five minutes before trying again.");
    Request.Builder builder = new Request.Builder().url("https://api.telematics.hyundaiusa.com" + path);
    int offsetMillis = TimeZone.getDefault().getOffset(sfNow());
    String offset = offsetMillis % 3600000 == 0 ? String.valueOf(offsetMillis / 3600000) : String.valueOf(offsetMillis / 3600000.0);
    builder.header("Content-Type", "application/json;charset=UTF-8")
        .header("Accept", "application/json, text/plain, */*").header("from", "SPA").header("to", "ISS")
        .header("language", "0").header("offset", offset)
        .header("refresh", "false").header("encryptFlag", "false").header("brandIndicator", "H")
        .header("client_id", "m66129Bb-em93-SPAHYN-bZ91-am4540zp19920")
        .header("clientSecret", "v558o935-6nne-423i-baa8")
        .header("Origin", "https://api.telematics.hyundaiusa.com")
        .header("Referer", "https://api.telematics.hyundaiusa.com/login");
    if (auth) {
        if (!sfSession.containsKey("token") || sfNow() >= ((Number)sfSession.get("expires")).longValue())
            sfFail("Login expired. Run SFD Connect. No command was sent.");
        builder.header("username", sfHeader(sfSession.get("email")))
            .header("accessToken", sfHeader(sfSession.get("token")))
            .header("blueLinkServicePin", sfHeader(sfSession.get("pin")));
    }
    if (vehicle) {
        JSONObject selected = (JSONObject)sfSession.get("vehicle");
        if (selected == null) sfFail("No vehicle is selected. Run SFD Choose Vehicle.");
        builder.header("registrationId", sfHeader(selected.optString("regid")))
            .header("gen", sfHeader(selected.optString("vehicleGeneration", "2")))
            .header("vin", sfHeader(selected.optString("vin")));
    }
    if (extra != null) for (Object key : extra.keySet()) builder.header(sfHeader(key), sfHeader(extra.get(key)));
    if (method.equals("GET")) builder.get();
    else {
        byte[] bytes = body == null ? new byte[0] : body.toString().getBytes("UTF-8");
        builder.post(RequestBody.create(MediaType.parse("application/json;charset=UTF-8"), bytes));
    }
    Response response = null; JSONObject result = null;
    try {
        response = sfClient.newCall(builder.build()).execute();
        int status = response.code();
        tasker.setVariable("SFDLastHttp", String.valueOf(status));
        if (status == 429) {
            tasker.setVariable("SFDWaitUntil", String.valueOf(sfNow() + 300000));
            sfFail("Hyundai rate limited requests. Wait five minutes before trying again. No retry was sent.");
        }
        if (status == 401 || status == 403) {
            sfSession.remove("token"); sfSession.put("expires", Long.valueOf(0)); sfSession.put("authBlocked", Boolean.TRUE);
        }
        if (status < 200 || status >= 300)
            sfFail("Hyundai returned HTTP " + status + ". No retry was sent. Check SFDLastHttp and your account if needed.");
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        InputStream stream = response.body() == null ? null : response.body().byteStream();
        if (stream != null) {
            byte[] block = new byte[4096]; int count;
            while ((count = stream.read(block)) != -1) {
                if (bytes.size() + count > 1048576) sfFail("Hyundai response exceeded the size limit. No retry was sent.");
                bytes.write(block, 0, count);
            }
        }
        String content = new String(bytes.toByteArray(), "UTF-8").trim();
        JSONObject data = content.length() == 0 ? new JSONObject() : new JSONObject(content);
        if (data.has("errorCode") || data.has("error")) sfFail("Hyundai reported an API error. No retry was sent.");
        String id = response.header("tmstid");
        if (id == null) id = response.header("transactionid");
        if (id == null) id = response.header("xid");
        result = new JSONObject().put("data", data).put("http", status);
        if (id != null) result.put("tid", id);
    } finally { if (response != null) response.close(); }
    // Older BeanShell versions lose a return value when finally ends in void.
    return result;
}
void sfCheckAccount() {
    String email = sfValue("SFDEmail").trim(); String password = sfValue("SFDPassword"); String pin = sfValue("SFDPin").trim();
    if (email.length() == 0 || email.length() > 320 || password.length() == 0 || password.length() > 4096 || !pin.matches("[0-9]{4}"))
        sfFail("Run SFD Setup once to enter your email, password and four-digit Bluelink PIN.");
    sfHeader(email); sfHeader(pin);
    String identity = sfIdentity(email, password, pin);
    if (!identity.equals(sfSession.get("identity"))) {
        if (sfMarkerFile.exists()) sfFail("Account changed while a command outcome is unresolved. Check the vehicle, then run SFD Resolve Unknown.");
        sfSession.clear(); sfSession.put("identity", identity);
    }
    sfSession.put("email", email); sfSession.put("pin", pin);
}
void sfSelectVehicle() {
    JSONArray list = (JSONArray)sfSession.get("vehicles"); String preferred = sfValue("SFDVin").trim().toUpperCase(Locale.US);
    JSONObject selected = null;
    if (list != null) for (int i = 0; i < list.length(); i++) {
        JSONObject vehicle = list.getJSONObject(i);
        if (preferred.length() > 0 && preferred.equals(vehicle.optString("vin"))) selected = vehicle;
        else if (preferred.length() == 0 && list.length() == 1) selected = vehicle;
    }
    if (selected == null) {
        sfSession.remove("vehicle");
        sfFail("Choose your active Santa Fe using SFD Choose Vehicle. No vehicle command was sent.");
    }
    sfSession.put("vehicle", selected);
}
void sfLogin() {
    sfSession.remove("token"); sfSession.put("expires", Long.valueOf(0)); sfSession.put("authBlocked", Boolean.TRUE);
    JSONObject body = new JSONObject().put("username", sfSession.get("email")).put("password", sfValue("SFDPassword"));
    JSONObject result = sfRequest("POST", "/v2/ac/oauth/token", body, false, false, null).getJSONObject("data");
    String token = result.optString("access_token"); long expires = result.optLong("expires_in", 1800);
    if (token.length() == 0 || expires <= 0) sfFail("Hyundai did not return a usable login. Check MyHyundai, then run SFD Connect.");
    sfHeader(token);
    sfSession.put("token", token); sfSession.put("expires", Long.valueOf(sfNow() + Math.min(expires, 86400) * 1000 - Math.min(30000, expires * 100)));
    JSONObject enrollment = sfRequest("GET", sfEnrollmentPath((String)sfSession.get("email")), null, true, false, null).getJSONObject("data");
    JSONArray source = enrollment.optJSONArray("enrolledVehicleDetails");
    if (source == null) sfFail("Hyundai returned no expected vehicle list. No command was sent.");
    JSONArray vehicles = new JSONArray();
    for (int i = 0; i < source.length(); i++) {
        JSONObject item = source.optJSONObject(i); JSONObject vehicle = item == null ? null : item.optJSONObject("vehicleDetails");
        if (vehicle != null && vehicle.optString("vin").matches("[A-HJ-NPR-Z0-9]{17}") && vehicle.optString("regid").length() > 0
                && vehicle.optString("enrollmentStatus").equals("ACTIVE")) vehicles.put(vehicle);
    }
    sfSession.put("vehicles", vehicles); sfSession.remove("vehicle");
    sfSession.put("authBlocked", Boolean.FALSE);
    sfSelectVehicle();
}
void sfEnsureSession(boolean explicit) {
    sfCheckAccount();
    if (!explicit && Boolean.TRUE.equals(sfSession.get("authBlocked")))
        sfFail("A previous account or authentication request failed. Check MyHyundai and run SFD Connect. No command was sent.");
    if (!sfSession.containsKey("token") || sfNow() >= ((Number)sfSession.get("expires")).longValue()) sfLogin();
    else sfSelectVehicle();
}
String sfStatus(boolean refresh) {
    Map extra = new HashMap(); extra.put("refresh", refresh ? "true" : "false");
    JSONObject data = sfRequest("GET", "/ac/v2/rcs/rvs/vehicleStatus", null, true, true, extra).getJSONObject("data");
    JSONObject status = data.optJSONObject("vehicleStatus");
    if (status == null) sfFail("Hyundai returned no expected vehicle status. No command was sent.");
    sfSession.put("statusRead", Boolean.TRUE);
    String timestamp = status.optString("dateTime", "Unknown");
    if (timestamp.length() > 60 || !timestamp.matches("[0-9TtZz:+ .\\-/]*")) timestamp = "Unknown";
    tasker.setVariable("SFDVehicleTime", timestamp);
    String lock = status.has("doorLock") && status.opt("doorLock") instanceof Boolean ? (status.getBoolean("doorLock") ? "Locked" : "Unlocked") : "Unknown";
    String engine = status.has("engine") && status.opt("engine") instanceof Boolean ? (status.getBoolean("engine") ? "Running" : "Off") : "Unknown";
    String climate = status.has("airCtrlOn") && status.opt("airCtrlOn") instanceof Boolean ? (status.getBoolean("airCtrlOn") ? "On" : "Off") : "Unknown";
    tasker.setVariable("SFDDoorLock", lock); tasker.setVariable("SFDEngine", engine); tasker.setVariable("SFDClimate", climate);
    String summary = "Doors: " + lock + "\nEngine: " + engine + "\nClimate: " + climate + "\nVehicle timestamp: " + timestamp
        + "\nHyundai may return cached data, including after a refresh request.";
    tasker.setVariable("SFDStatus", summary); return summary;
}
JSONObject sfCommandRecipe(String operation) {
    JSONObject selected = (JSONObject)sfSession.get("vehicle");
    if (selected == null || !selected.optString("enrollmentStatus").equals("ACTIVE")) sfFail("Select an active vehicle first. No command was sent.");
    Map extra = new HashMap(); JSONObject body = null; String path = "";
    if (operation.equals("lock") || operation.equals("unlock")) {
        path = operation.equals("lock") ? "/ac/v2/rcs/rdo/off" : "/ac/v2/rcs/rdo/on";
        body = new JSONObject().put("userName", sfSession.get("email")).put("vin", selected.getString("vin"));
        extra.put("APPCLOUD-VIN", selected.getString("vin"));
    } else if (operation.equals("start") || operation.equals("stop")) {
        // This project targets the confirmed non-EV Santa Fe Hybrid recipe only.
        if (!selected.optString("evStatus").equals("N") || selected.optInt("vehicleGeneration") != 3)
            sfFail("The selected vehicle does not match the confirmed Santa Fe Hybrid generation 3 recipe. No command was sent.");
        path = operation.equals("start") ? "/ac/v2/rcs/rsc/start" : "/ac/v2/rcs/rsc/stop";
        if (operation.equals("start")) {
            int temperature = 72; int duration = 10;
            try {
                if (sfValue("SFDTemperature").length() > 0) temperature = Integer.parseInt(sfValue("SFDTemperature"));
                if (sfValue("SFDDuration").length() > 0) duration = Integer.parseInt(sfValue("SFDDuration"));
            } catch (Exception invalid) { sfFail("Use whole-number climate temperature and duration. No command was sent."); }
            if (temperature < 62 || temperature > 81 || duration < 1 || duration > 10)
                sfFail("Climate temperature must be 62 to 81 F and duration 1 to 10 minutes. No command was sent.");
            String defrost = sfValue("SFDDefrost");
            if (defrost.length() > 0 && !defrost.equals("0") && !defrost.equals("1")) sfFail("Defrost must be 0 or 1. No command was sent.");
            JSONObject seat = new JSONObject().put("drvSeatHeatState", 0).put("astSeatHeatState", 0).put("rlSeatHeatState", 0).put("rrSeatHeatState", 0);
            body = new JSONObject().put("Ims", 0).put("airCtrl", 1).put("airTemp", new JSONObject().put("unit", 1).put("value", temperature))
                .put("defrost", defrost.equals("1")).put("heating1", 0).put("igniOnDuration", duration).put("seatHeaterVentInfo", seat)
                .put("username", sfSession.get("email")).put("vin", selected.getString("regid"));
        }
    } else sfFail("This control is unavailable. No command was sent.");
    return new JSONObject().put("path", path).put("body", body == null ? JSONObject.NULL : body).put("extra", new JSONObject(extra));
}


// Native dialogs. Tasker supplies its Activity and bundled RxJava2 library.
import android.app.Activity;
import android.app.AlertDialog;
import android.content.DialogInterface;
import android.view.WindowManager;
import android.widget.*;
import android.text.InputType;
import java.util.function.Consumer;
import io.reactivex.subjects.SingleSubject;

String sfConfirm(String title, String message, String button) {
    signal = SingleSubject.create();
    tasker.doWithActivity(new Consumer() {
        accept(Object object) {
            final Activity activity = (Activity)object;
            activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
            AlertDialog.Builder builder = new AlertDialog.Builder(activity).setTitle(title).setMessage(message).setCancelable(false);
            builder.setPositiveButton(button, new DialogInterface.OnClickListener() {
                onClick(DialogInterface dialog, int which) { signal.onSuccess("yes"); activity.finish(); }
            });
            builder.setNegativeButton("Cancel", new DialogInterface.OnClickListener() {
                onClick(DialogInterface dialog, int which) { signal.onSuccess("no"); activity.finish(); }
            });
            builder.show();
        }
    });
    return (String)signal.blockingGet();
}
void sfMessage(String title, String message) {
    signal = SingleSubject.create();
    tasker.doWithActivity(new Consumer() {
        accept(Object object) {
            final Activity activity = (Activity)object;
            activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
            new AlertDialog.Builder(activity).setTitle(title).setMessage(message).setCancelable(false)
                .setPositiveButton("OK", new DialogInterface.OnClickListener() {
                    onClick(DialogInterface dialog, int which) { signal.onSuccess("ok"); activity.finish(); }
                }).show();
        }
    });
    signal.blockingGet();
}
String sfChoose(String title, String[] choices, String[] values) {
    signal = SingleSubject.create();
    tasker.doWithActivity(new Consumer() {
        accept(Object object) {
            final Activity activity = (Activity)object;
            activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
            AlertDialog.Builder builder = new AlertDialog.Builder(activity).setTitle(title).setCancelable(false);
            builder.setItems(choices, new DialogInterface.OnClickListener() {
                onClick(DialogInterface dialog, int which) { signal.onSuccess(values[which]); activity.finish(); }
            });
            builder.setNegativeButton("Cancel", new DialogInterface.OnClickListener() {
                onClick(DialogInterface dialog, int which) { signal.onSuccess("cancel"); activity.finish(); }
            });
            builder.show();
        }
    });
    return (String)signal.blockingGet();
}
JSONObject sfAccountForm() {
    signal = SingleSubject.create();
    tasker.doWithActivity(new Consumer() {
        accept(Object object) {
            final Activity activity = (Activity)object;
            activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
            LinearLayout layout = new LinearLayout(activity); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(24, 12, 24, 12);
            TextView explanation = new TextView(activity); explanation.setText("Enter once. Blank password or PIN keeps the saved value. Leave VIN blank to select the only active vehicle."); layout.addView(explanation);
            EditText email = new EditText(activity); email.setHint("MyHyundai email"); email.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS); email.setSingleLine(true); email.setText(sfValue("SFDEmail")); layout.addView(email);
            EditText password = new EditText(activity); password.setHint("Password"); password.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD); password.setSingleLine(true); layout.addView(password);
            EditText pin = new EditText(activity); pin.setHint("Four-digit Bluelink PIN"); pin.setInputType(InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_VARIATION_PASSWORD); pin.setSingleLine(true); layout.addView(pin);
            EditText vin = new EditText(activity); vin.setHint("VIN (optional)"); vin.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS); vin.setSingleLine(true); vin.setText(sfValue("SFDVin")); layout.addView(vin);
            ScrollView scroll = new ScrollView(activity); scroll.addView(layout);
            AlertDialog dialog = new AlertDialog.Builder(activity).setTitle("Santa Fe account").setView(scroll).setCancelable(false).setPositiveButton("Save", null)
                .setNegativeButton("Cancel", new DialogInterface.OnClickListener() {
                    onClick(DialogInterface dialog, int which) { signal.onSuccess(new JSONObject().put("cancel", true)); activity.finish(); }
                }).create();
            dialog.show();
            dialog.getButton(DialogInterface.BUTTON_POSITIVE).setOnClickListener(new android.view.View.OnClickListener() {
                onClick(android.view.View view) {
                    String enteredEmail = email.getText().toString().trim(); String enteredPassword = password.getText().toString(); String enteredPin = pin.getText().toString().trim();
                    String enteredVin = vin.getText().toString().trim().toUpperCase(Locale.US);
                    if (enteredPassword.length() == 0) enteredPassword = sfValue("SFDPassword");
                    if (enteredPin.length() == 0) enteredPin = sfValue("SFDPin");
                    if (enteredEmail.length() == 0 || enteredEmail.length() > 320 || enteredEmail.indexOf('\n') >= 0 || enteredEmail.indexOf('\r') >= 0) { email.setError("Enter your email"); return; }
                    if (enteredPassword.length() == 0 || enteredPassword.length() > 4096) { password.setError("Enter your password"); return; }
                    if (!enteredPin.matches("[0-9]{4}")) { pin.setError("Use four digits"); return; }
                    if (enteredVin.length() > 0 && !enteredVin.matches("[A-HJ-NPR-Z0-9]{17}")) { vin.setError("Use a 17-character VIN, or leave blank"); return; }
                    signal.onSuccess(new JSONObject().put("email", enteredEmail).put("password", enteredPassword).put("pin", enteredPin).put("vin", enteredVin));
                    password.setText(""); pin.setText(""); dialog.dismiss(); activity.finish();
                }
            });
        }
    });
    return (JSONObject)signal.blockingGet();
}
JSONObject sfClimateForm() {
    signal = SingleSubject.create();
    tasker.doWithActivity(new Consumer() {
        accept(Object object) {
            final Activity activity = (Activity)object;
            activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
            LinearLayout layout = new LinearLayout(activity); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(24, 12, 24, 12);
            TextView explanation = new TextView(activity); explanation.setText("Temperature: 62 to 81 F. Duration: 1 to 10 minutes. Seats and steering-wheel heat remain off."); layout.addView(explanation);
            EditText temperature = new EditText(activity); temperature.setHint("Temperature (F)"); temperature.setInputType(InputType.TYPE_CLASS_NUMBER); temperature.setText(sfValue("SFDTemperature").length() == 0 ? "72" : sfValue("SFDTemperature")); layout.addView(temperature);
            EditText duration = new EditText(activity); duration.setHint("Minutes"); duration.setInputType(InputType.TYPE_CLASS_NUMBER); duration.setText(sfValue("SFDDuration").length() == 0 ? "10" : sfValue("SFDDuration")); layout.addView(duration);
            CheckBox defrost = new CheckBox(activity); defrost.setText("Defrost"); defrost.setChecked(sfValue("SFDDefrost").equals("1")); layout.addView(defrost);
            AlertDialog dialog = new AlertDialog.Builder(activity).setTitle("Remote start settings").setView(layout).setCancelable(false).setPositiveButton("Save", null)
                .setNegativeButton("Cancel", new DialogInterface.OnClickListener() {
                    onClick(DialogInterface dialog, int which) { signal.onSuccess(new JSONObject().put("cancel", true)); activity.finish(); }
                }).create();
            dialog.show();
            dialog.getButton(DialogInterface.BUTTON_POSITIVE).setOnClickListener(new android.view.View.OnClickListener() {
                onClick(android.view.View view) {
                    int temp = 0; int minutes = 0;
                    try { temp = Integer.parseInt(temperature.getText().toString()); } catch (Exception ignored) {}
                    try { minutes = Integer.parseInt(duration.getText().toString()); } catch (Exception ignored) {}
                    if (temp < 62 || temp > 81) { temperature.setError("Use 62 to 81"); return; }
                    if (minutes < 1 || minutes > 10) { duration.setError("Use 1 to 10"); return; }
                    signal.onSuccess(new JSONObject().put("temperature", temp).put("duration", minutes).put("defrost", defrost.isChecked()));
                    dialog.dismiss(); activity.finish();
                }
            });
        }
    });
    return (JSONObject)signal.blockingGet();
}


// Santa Fe Direct 1.0.0 entry and command state. Credentials are Tasker settings.
// Tokens and transaction details stay in a volatile global Java object.
import java.nio.channels.*;
import java.util.concurrent.locks.ReentrantLock;

void sfSaveMarker(String operation) {
    JSONObject marker = new JSONObject().put("action", operation).put("time", sfNow());
    File temporary = new File(sfMarkerFile.getPath() + ".tmp");
    FileOutputStream out = new FileOutputStream(temporary);
    try { out.write(marker.toString().getBytes("UTF-8")); out.getFD().sync(); } finally { out.close(); }
    if (!temporary.renameTo(sfMarkerFile)) sfFail("Could not save the pending-command guard. No command was sent.");
    if (!sfMarkerFile.isFile() || sfMarkerFile.length() == 0) sfFail("Could not verify the pending-command guard. No command was sent.");
}
void sfClearMarker() {
    if (sfMarkerFile.exists() && !sfMarkerFile.delete()) sfFail("Could not clear the pending-command guard. Check the vehicle before running SFD Resolve Unknown.");
    if (sfMarkerFile.exists()) sfFail("The pending-command guard is still present. No further command will be sent.");
    sfSession.remove("pending");
}
String sfPollOnce() {
    if (!sfMarkerFile.exists()) sfFail("No command is waiting for a result.");
    JSONObject pending = (JSONObject)sfSession.get("pending");
    if (pending == null || pending.optString("tid").length() == 0)
        sfFail("The previous command has no readable transaction in this session. Check the vehicle, then run SFD Resolve Unknown. It will not be retried.");
    JSONObject selected = (JSONObject)sfSession.get("vehicle");
    if (!pending.optString("vin").equals(selected.optString("vin")) || !pending.optString("regid").equals(selected.optString("regid"))
        || !pending.optString("identity").equals(sfSession.get("identity")))
        sfFail("Return to the account and vehicle that received the pending command. No command was sent.");
    Map extra = new HashMap(); extra.put("tid", pending.getString("tid")); extra.put("login_id", sfSession.get("email")); extra.put("service_type", "REMOTE_POLL");
    JSONObject data = sfRequest("GET", "/ac/v2/rmt/getRunningStatus", null, true, true, extra).getJSONObject("data");
    if (data.has("tid") && !pending.getString("tid").equals(data.optString("tid"))) sfFail("Hyundai returned a different transaction. The command outcome remains unresolved.");
    String status = data.optString("status");
    if (status.equals("SUCCESS")) { sfClearMarker(); return "SUCCESS"; }
    if (status.equals("ERROR")) { sfClearMarker(); return "FAILED"; }
    // The upstream client uses a fixed polling delay. The tester establishes
    // response states, but not the unit of nextPollingInterval. Do not guess it.
    int interval = 10;
    pending.put("interval", interval); pending.put("nextAllowedAt", sfNow() + interval * 1000L);
    return status.equals("PENDING") ? "PENDING" : "UNKNOWN";
}
String sfPollBounded(boolean waitFirst) {
    long deadline = sfNow() + 120000; int count = 0;
    if (waitFirst) sfDelay(10000);
    else {
        JSONObject previous = (JSONObject)sfSession.get("pending");
        long delay = previous == null ? 0 : previous.optLong("nextAllowedAt", sfNow()) - sfNow();
        if (delay >= 120000) return "PENDING";
        if (delay > 0) sfDelay(delay);
    }
    String outcome = "PENDING";
    while (count < 10 && sfNow() < deadline) {
        outcome = sfPollOnce(); count++;
        if (!outcome.equals("PENDING")) return outcome;
        JSONObject pending = (JSONObject)sfSession.get("pending");
        long delay = pending.optInt("interval", 10) * 1000L;
        if (sfNow() + delay >= deadline || count >= 10) break;
        sfDelay(delay);
    }
    return outcome;
}
String sfSubmit(String operation) {
    if (sfMarkerFile.exists()) sfFail("A previous command outcome is unresolved. Run SFD Check Command or check the vehicle and use SFD Resolve Unknown. No new command was sent.");
    JSONObject recipe = sfCommandRecipe(operation);
    if (operation.equals("start") && !sfConfirm("Remote start", "Is the vehicle parked outdoors, clear of people and safe to start?", "Start").equals("yes")) return "CANCELLED";
    // Obtain an actual status object before control submission, as in the tester.
    sfStatus(false);
    JSONObject selected = (JSONObject)sfSession.get("vehicle");
    JSONObject pending = new JSONObject().put("action", operation).put("vin", selected.getString("vin"))
        .put("regid", selected.getString("regid")).put("identity", sfSession.get("identity"));
    sfSaveMarker(operation); sfSession.put("pending", pending);
    Map extra = new HashMap(); JSONObject values = recipe.getJSONObject("extra");
    for (Iterator keys = values.keys(); keys.hasNext();) { String key = (String)keys.next(); extra.put(key, values.getString(key)); }
    JSONObject body = recipe.isNull("body") ? null : recipe.getJSONObject("body");
    JSONObject result = sfRequest("POST", recipe.getString("path"), body, true, true, extra);
    String id = result.optString("tid");
    if (id.length() == 0) return "UNKNOWN";
    sfHeader(id); pending.put("tid", id);
    tasker.showToast("Hyundai accepted " + operation + ". Checking completion...");
    return sfPollBounded(true);
}
String sfReport(String state, String message) {
    tasker.setVariable("SFDState", state); tasker.setVariable("SFDResult", message);
    tasker.showToast(message); return message;
}

String sfDispatch(String operation) {
    if (operation.equals("controls")) {
        operation = sfChoose("Santa Fe controls", new String[]{"Status", "Refresh status", "Lock", "Unlock", "Remote start", "Remote stop", "Check command", "Account settings", "Climate settings"},
            new String[]{"status", "refresh", "lock", "unlock", "start", "stop", "poll", "setup", "climate"});
    }
    if (operation.equals("cancel")) return sfReport("CANCELLED", "Cancelled. No request was sent.");
    if (operation.equals("verify")) {
        int actions = tasker.getTask().getActionCount();
        if (actions < 1) sfFail("Tasker reports no executable actions.");
        return sfReport("READY", "Santa Fe Direct 1.0.0 loaded. Core has " + actions + " executable action(s). Java, JSON and HTTP libraries are available. No network request was made.");
    }
    if (operation.equals("setup")) {
        if (sfMarkerFile.exists()) sfFail("Check the pending command before changing account settings. Use SFD Check Command or SFD Resolve Unknown.");
        JSONObject account = sfAccountForm();
        if (account.optBoolean("cancel")) return sfReport("CANCELLED", "Account settings unchanged.");
        tasker.setVariable("SFDEmail", account.getString("email")); tasker.setVariable("SFDPassword", account.getString("password"));
        tasker.setVariable("SFDPin", account.getString("pin")); tasker.setVariable("SFDVin", account.getString("vin"));
        sfSession.clear();
        return sfReport("SAVED", "Account saved in Tasker. Run SFD Connect once to verify it. No request was sent during setup.");
    }
    if (operation.equals("climate")) {
        JSONObject settings = sfClimateForm();
        if (settings.optBoolean("cancel")) return sfReport("CANCELLED", "Climate settings unchanged.");
        tasker.setVariable("SFDTemperature", String.valueOf(settings.getInt("temperature")));
        tasker.setVariable("SFDDuration", String.valueOf(settings.getInt("duration")));
        tasker.setVariable("SFDDefrost", settings.getBoolean("defrost") ? "1" : "0");
        return sfReport("SAVED", "Remote start settings saved. No vehicle command was sent.");
    }
    if (operation.equals("clear")) { sfSession.clear(); return sfReport("CLEARED", "Live login cleared. Saved account and any pending-command guard are retained."); }
    if (operation.equals("forget")) {
        if (!sfConfirm("Forget account", "Remove the email, password, PIN and selected VIN saved in this Tasker project? A pending command warning will remain.", "Forget").equals("yes")) return sfReport("CANCELLED", "Account settings unchanged.");
        for (String name : new String[]{"SFDEmail", "SFDPassword", "SFDPin", "SFDVin"}) tasker.setVariable(name, "");
        sfSession.clear(); return sfReport("FORGOTTEN", "Account cleared from Tasker variables. Any earlier Tasker backups are separate. Pending-command guard retained.");
    }
    if (operation.equals("resolve")) {
        if (!sfMarkerFile.exists()) return sfReport("READY", "No unresolved command is recorded.");
        if (!sfConfirm("Unresolved command", "Check the car or MyHyundai first. Have you confirmed what the vehicle actually did? This clears the warning only. It does not cancel or repeat a command.", "I checked the vehicle").equals("yes")) return sfReport("CANCELLED", "Pending-command guard retained.");
        sfClearMarker(); return sfReport("ACKNOWLEDGED", "Physical outcome acknowledged. No API command was sent or retried.");
    }
    if (!Arrays.asList(new String[]{"connect", "choose", "status", "refresh", "lock", "unlock", "start", "stop", "poll"}).contains(operation))
        sfFail("Unknown task operation. No request was sent.");
    if (operation.equals("choose")) {
        if (sfMarkerFile.exists()) sfFail("Check the pending command before switching vehicles.");
        sfCheckAccount();
        if (!sfSession.containsKey("token") || sfNow() >= ((Number)sfSession.get("expires")).longValue()) {
            try { sfLogin(); } catch (IOException selectNeeded) {
                if (!sfSession.containsKey("vehicles") || Boolean.TRUE.equals(sfSession.get("authBlocked"))) throw selectNeeded;
            }
        }
        JSONArray vehicles = (JSONArray)sfSession.get("vehicles");
        if (vehicles == null || vehicles.length() == 0) sfFail("Hyundai returned no active vehicles.");
        String[] labels = new String[vehicles.length()]; String[] vins = new String[vehicles.length()];
        for (int i = 0; i < vehicles.length(); i++) {
            JSONObject vehicle = vehicles.getJSONObject(i); vins[i] = vehicle.getString("vin");
            labels[i] = "Vehicle " + (i + 1) + " | VIN ending " + vins[i].substring(13);
        }
        String chosen = sfChoose("Choose your Santa Fe", labels, vins);
        if (chosen.equals("cancel")) return sfReport("CANCELLED", "Vehicle selection unchanged.");
        tasker.setVariable("SFDVin", chosen); sfSelectVehicle();
        return sfReport("SELECTED", "Vehicle selected. Run SFD Status.");
    }
    // With an unresolved outcome, controls are blocked before even logging in.
    if (Arrays.asList(new String[]{"lock", "unlock", "start", "stop"}).contains(operation) && sfMarkerFile.exists())
        sfFail("A previous command outcome is unresolved. Run SFD Check Command or check the vehicle and use SFD Resolve Unknown. No new request was sent.");
    if (operation.equals("poll")) {
        JSONObject previous = (JSONObject)sfSession.get("pending");
        if (!sfMarkerFile.exists()) sfFail("No command is waiting for a result.");
        if (previous == null || previous.optString("tid").length() == 0)
            sfFail("The previous command has no readable transaction in this session. Check the vehicle, then run SFD Resolve Unknown. It will not be retried.");
    }
    sfEnsureSession(operation.equals("connect"));
    if (operation.equals("connect") || operation.equals("status") || operation.equals("refresh")) {
        String status = sfStatus(operation.equals("refresh"));
        sfReport("READ", (operation.equals("connect") ? "Connected.\n" : "") + status);
        if (!operation.equals("connect")) sfMessage("Santa Fe status", status);
        return sfValue("SFDResult");
    }
    String state = operation.equals("poll") ? sfPollBounded(false) : sfSubmit(operation);
    String message = state.equals("SUCCESS") ? "Hyundai confirmed command completion (SUCCESS)."
        : state.equals("FAILED") ? "Hyundai reported command failure (ERROR). No retry was sent."
        : state.equals("CANCELLED") ? "Cancelled. No vehicle command was sent."
        : state.equals("PENDING") ? "Command is still pending. Run SFD Check Command later. It will not be resubmitted."
        : "Command outcome is unknown. Check the vehicle before SFD Resolve Unknown. It will not be retried.";
    return sfReport(state, message);
}

// ENTRY: the generator embeds api.java, ui.java and this file into one action.
String operation = sfValue("par1");
if (operation.length() == 0) operation = "verify";
Map sfSession = null;
File sfMarkerFile = new File(context.getNoBackupFilesDir(), "santa-fe-direct-pending.json");
RandomAccessFile sfLockFile = null; FileLock sfLock = null;
OkHttpClient sfClient = sfMakeClient();
String sfOutput = "";
ReentrantLock sfMutex = null; boolean sfMutexHeld = false;
try {
    synchronized ("santa.fe.direct.operation".intern()) {
        sfMutex = (ReentrantLock)tasker.getGlobalJavaVariables().get("sfDirectLock");
        if (sfMutex == null) { sfMutex = new ReentrantLock(); tasker.setJavaVariable("sfDirectLock", sfMutex); }
    }
    sfMutexHeld = sfMutex.tryLock();
    if (!sfMutexHeld) sfFail("Another Santa Fe task is running. No new request was sent.");
    sfLockFile = new RandomAccessFile(new File(context.getNoBackupFilesDir(), "santa-fe-direct.lock"), "rw");
    try { sfLock = sfLockFile.getChannel().tryLock(); } catch (OverlappingFileLockException busy) {}
    if (sfLock == null) sfOutput = sfReport("BUSY", "Another Santa Fe task is running. No new request was sent.");
    else {
        sfSession = (Map)tasker.getGlobalJavaVariables().get("sfDirectSession");
        if (sfSession == null) { sfSession = new HashMap(); tasker.setJavaVariable("sfDirectSession", sfSession); }
        tasker.setVariable("SFDLastHttp", "");
        sfOutput = sfDispatch(operation);
    }

} catch (Exception failure) {
    String message = failure.getMessage();
    if (message == null || !message.startsWith("SF: ")) message = "Connection or response failed. No request was retried.";
    else message = message.substring(4);
    boolean unresolved = sfMarkerFile.exists();
    if (unresolved) message += " A previous command may have reached the car. Run SFD Check Command or check the vehicle before SFD Resolve Unknown.";
    sfOutput = sfReport(unresolved ? "UNKNOWN" : "FAILED", message);
} finally {
    try {
        if (sfLock != null) sfLock.release();
    } finally {
        try { if (sfLockFile != null) sfLockFile.close(); }
        finally { if (sfMutexHeld) sfMutex.unlock(); }
    }
}

return sfOutput;
